const expected = $env.SAIBAI_ECOM_WEBHOOK_TOKEN || '';
const headers = $json.headers || {};
const received = String(headers['x-veltrus-token'] || headers['X-Veltrus-Token'] || '');
if (expected && received !== expected) {
  throw new Error('Unauthorized e-com sale webhook.');
}
const raw = $json.body ?? $json;
const b = typeof raw === 'string' ? JSON.parse(raw) : raw;
const orderId = String(b.order_id || b.orderId || b.transaction_id || b.txId || '').trim();
if (!orderId) throw new Error('order_id required');
const revenue = Number(b.revenue ?? b.value ?? b.total_price ?? 0);
const currency = String(b.currency || 'BRL').toUpperCase();
const source = String(b.utm_source || b.source || b.session_source || '—').trim();
const orderNumber = String(b.order_number || b.orderNumber || orderId).trim();
const lines = [
  'Emporio Saibai · NOVA VENDA',
  `Pedido: ${orderNumber}`,
  `ID: ${orderId}`,
  `Valor: R$ ${revenue.toFixed(2).replace('.', ',')}`,
  `Moeda: ${currency}`,
  `Canal: ${source}`,
  `Detectado: ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`,
  '',
  'Fonte: n8n webhook · Shopify/GA4/Supabase',
];
const phones = String($env.SAIBAI_SALES_WHATSAPP || $env.SAIBAI_ALERT_WHATSAPP_LIST || $env.NOTIFY_PHONE_NUMBER || '')
  .split(',')
  .map((p) => p.trim().replace(/\D/g, ''))
  .filter(Boolean);
if (!phones.length) throw new Error('SAIBAI_SALES_WHATSAPP ausente');
return phones.map((phone) => ({ json: { phone, text: lines.join('\n'), orderId, revenue } }));
